g? // Encrypted webhook secret\n  webhookId     String? // GitHub webhook ID\n\n  // Sync preferences\n  importAllRuns Boolean @default(false) // Import all workflow runs\n  autoSync      Boolean @default(true) // Auto-sync on webhook events\n  syncInterval  Int? // Sync interval in minutes (null = manual only)\n\n  // Relationships\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  repositoryTokens  RepositoryToken[]\n  workflows         Workflow[]\n  branchPermissions BranchPermission[]\n  syncJobs          SyncJob[]\n  webhookEvents     WebhookEvent[]\n\n  // Metadata\n  createdAt         DateTime            @default(now())\n  updatedAt         DateTime            @updatedAt\n  deletedAt         DateTime?\n  AnalyticsSnapshot AnalyticsSnapshot[]\n\n  @@index([userId])\n  @@index([githubOwner, name])\n  @@map("repositories")\n}\n\nmodel RepositoryToken {\n  id         String    @id @default(cuid())\n  token      String // The actual token (encrypted)\n  alias      String? // User-friendly name for the token\n  type       TokenType @default(PRIVATE)\n  isActive   Boolean   @default(true)\n  lastUsedAt DateTime?\n  expiresAt  DateTime? // Token expiration date\n\n  // GitHub user details (from token validation)\n  githubUserId BigInt?\n  githubLogin  String?\n  githubEmail  String?\n  githubName   String?\n  avatarUrl    String?\n  scopes       String[] // GitHub token scopes\n\n  // Relationships\n  repositoryId String\n  repository   Repository @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n\n  userId String\n  user   User   @relation("TokenOwner", fields: [userId], references: [id], onDelete: Cascade)\n\n  // Metadata\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([repositoryId])\n  @@index([userId])\n  @@index([type, isActive])\n  @@map("repository_tokens")\n}\n\n// =========================================================